using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using UnityEngine;
using Doppel6.Probe;
using Color=UnityEngine.Color;
// Scratch software rasteriser for self-review of stadium blueprints from the actual match cameras.
// Flat Lambert shading with the evening key light; not a Unity render.
public sealed class Raster {
    public readonly int W,H;readonly float[] depth;readonly Color[] px;
    Vector3 cam,f,r,u;float tanHalf,aspect;
    public Raster(int w,int h){W=w;H=h;depth=new float[w*h];px=new Color[w*h];}
    public void Clear(Color top,Color horizon){for(int y=0;y<H;y++){float t=y/(float)H;var c=Color.Lerp(top,horizon,Mathf.Pow(t,1.6f));for(int x=0;x<W;x++){px[y*W+x]=c;depth[y*W+x]=float.MaxValue;}}}
    public void Camera(Vector3 position,Vector3 target,float fovDeg){cam=position;f=(target-position).normalized;r=Vector3.Cross(Vector3.up,f).normalized;u=Vector3.Cross(f,r);tanHalf=Mathf.Tan(fovDeg*.5f*Mathf.Deg2Rad);aspect=W/(float)H;}
    bool Project(Vector3 p,out Vector3 s){var v=p-cam;float z=Vector3.Dot(v,f);s=default;if(z<.3f)return false;float x=Vector3.Dot(v,r)/z/tanHalf/aspect,y=Vector3.Dot(v,u)/z/tanHalf;s=new Vector3((x+1)*.5f*W,(1-y)*.5f*H,z);return true;}
    public static readonly Vector3 Light=(Quaternion.Euler(54,-32,0)*Vector3.forward);
    public void Triangle(Vector3 a,Vector3 b,Vector3 c,Color albedo,Color emission,float ambient=.32f,float key=.9f){
        var n=Vector3.Cross(b-a,c-a).normalized;var toCam=(cam-(a+b+c)/3f).normalized;if(Vector3.Dot(n,toCam)<0)n=-n;
        float ndl=Mathf.Max(0,Vector3.Dot(n,-Light));var col=albedo*(ambient+key*ndl)+emission;col.a=1;
        if(!Project(a,out var A)||!Project(b,out var B)||!Project(c,out var C))return;
        int x0=Math.Max(0,(int)Math.Floor(Math.Min(A.x,Math.Min(B.x,C.x)))),x1=Math.Min(W-1,(int)Math.Ceiling(Math.Max(A.x,Math.Max(B.x,C.x))));
        int y0=Math.Max(0,(int)Math.Floor(Math.Min(A.y,Math.Min(B.y,C.y)))),y1=Math.Min(H-1,(int)Math.Ceiling(Math.Max(A.y,Math.Max(B.y,C.y))));
        if(x1-x0>W*3||y1-y0>H*3)return;
        float area=(B.x-A.x)*(C.y-A.y)-(B.y-A.y)*(C.x-A.x);if(Math.Abs(area)<1e-6f)return;
        for(int y=y0;y<=y1;y++)for(int x=x0;x<=x1;x++){float px_=x+.5f,py=y+.5f;
            float w0=((B.x-px_)*(C.y-py)-(B.y-py)*(C.x-px_))/area,w1=((C.x-px_)*(A.y-py)-(C.y-py)*(A.x-px_))/area,w2=1-w0-w1;
            if(w0<0||w1<0||w2<0)continue;float z=1/(w0/A.z+w1/B.z+w2/C.z);int i=y*W+x;if(z<depth[i]){depth[i]=z;px[i]=col;}}
    }
    public void Mesh(Mesh m,Color albedo,Color emission,bool vertexTint=true){
        var v=m.vertices;var t=m.triangles;var c=m.colors;
        for(int i=0;i<t.Length;i+=3){var tint=vertexTint&&c.Length>0?(c[t[i]]+c[t[i+1]]+c[t[i+2]])*(1/3f):Color.white;Triangle(v[t[i]],v[t[i+1]],v[t[i+2]],albedo*tint,emission);}
    }
    public Bitmap ToBitmap(){
        var bmp=new Bitmap(W,H,PixelFormat.Format24bppRgb);var data=bmp.LockBits(new Rectangle(0,0,W,H),ImageLockMode.WriteOnly,PixelFormat.Format24bppRgb);var bytes=new byte[data.Stride*H];
