        System.Runtime.InteropServices.Marshal.Copy(bytes,0,data.Scan0,bytes.Length);bmp.UnlockBits(data);return bmp;
    }
    public void Save(string path){
        using(var bmp=new Bitmap(W,H,PixelFormat.Format24bppRgb)){
            var data=bmp.LockBits(new Rectangle(0,0,W,H),ImageLockMode.WriteOnly,PixelFormat.Format24bppRgb);var bytes=new byte[data.Stride*H];
            for(int y=0;y<H;y++)for(int x=0;x<W;x++){var c=px[y*W+x];int o=y*data.Stride+x*3;bytes[o]=(byte)(Mathf.Clamp01(c.b)*255);bytes[o+1]=(byte)(Mathf.Clamp01(c.g)*255);bytes[o+2]=(byte)(Mathf.Clamp01(c.r)*255);}
