using System;
using System.Collections.Generic;
using UnityEngine;
using Doppel6.Probe;
using Color=UnityEngine.Color;
public static class SupporterPreview {
    public static SupporterSetup Setup(string home,string away,bool neutral=false){
        var (hp,hs)=Program.Colors(home);var (ap,as2)=Program.Colors(away);
        return new SupporterSetup{ClubIds=new[]{home,away},Primary=new[]{hp,ap},Secondary=new[]{hs,as2},Patterns=new[]{2,4},HomeTeam=0,Neutral=neutral};
    }
    // Draw supporter streams displaced to the given presentation time (mirror of the shader).
    public static void Draw(Raster r,SupporterPlan plan,bool[] shown,float time,float celebrate=0){
        foreach(var bp in plan.Blocks){if(!shown[bp.Block.Side])continue;
            Stream(r,bp.Figures,time,celebrate,null,bp);Stream(r,bp.Cloth,time,celebrate,bp,bp);}
    }
    static void Stream(Raster r,SupporterMesh m,float time,float celebrate,SupporterBlockPlan atlas,SupporterBlockPlan bp){
        var v=new Vector3[m.Vertices.Count];
        for(int i=0;i<v.Length;i++)v[i]=StadiumSupporters.Displace(m.Vertices[i],m.Normals[i],m.Motion[i],m.Pivots[i],(Vector3)m.Axes[i],time,celebrate);
        var t=m.Triangles;
        for(int i=0;i<t.Count;i+=3){Color c;
            if(atlas!=null){var uv=(m.Uv[t[i]]+m.Uv[t[i+1]]+m.Uv[t[i+2]])*(1/3f);c=StadiumSupporters.AtlasTexel(Mathf.Clamp((int)(uv.x*256),0,255),Mathf.Clamp((int)(uv.y*128),0,127),bp.Primary,bp.Secondary,bp.Pattern);}
            else{var lin=(m.Colors[t[i]]+m.Colors[t[i+1]]+m.Colors[t[i+2]])*(1/3f);c=lin.gamma;}
            r.Triangle(v[t[i]],v[t[i+1]],v[t[i+2]],c,Color.clear,.45f,.8f);}
    }
}

