using Doppel6.Probe;
public static class Visibility {
    // Fraction of ball positions (follow camera, near 60, 16:9, fov 42) where a block projects into the frame.
    public static void Run(){
        foreach(var id in new[]{"GER-1","GER-2","GER-3","GER-5","GER-6","GER-C1","NEUTRAL-EUROPE"}){
            var profile=id=="NEUTRAL-EUROPE"?ClubStadiumProfiles.NeutralEurope():ClubStadiumProfiles.Resolve(id);var plan=StadiumArchitecture.Plan(profile,68,44,Color.red,Color.white);
            var sp=StadiumSupporters.Plan(plan,new SupporterSetup{ClubIds=new[]{"A","B"},Primary=new[]{Color.red,Color.blue},Secondary=new[]{Color.white,Color.white},Patterns=new[]{0,1},HomeTeam=0,Neutral=profile.Identity.Supporters.Neutral},true);
            string line=id;
            foreach(var bp in sp.Blocks){int all=0,seen=0,half=0,halfSeen=0;
                for(float bx=-32;bx<=32;bx+=2)for(float bz=-18;bz<=18;bz+=4){var (cam,target)=Baseline.Camera("follow",new Vector3(bx,0,bz),60);
                    var f=(target-cam).normalized;var r=Vector3.Cross(Vector3.up,f).normalized;var u=Vector3.Cross(f,r);float th=Mathf.Tan(21*Mathf.Deg2Rad),aspect=16f/9;bool vis=false;
                    var v=bp.Figures.Vertices;for(int i=0;i<v.Count&&!vis;i+=9){var d=v[i]-cam;float z=Vector3.Dot(d,f);if(z<.5f)continue;float x=Vector3.Dot(d,r)/z/th/aspect,y=Vector3.Dot(d,u)/z/th;vis=Mathf.Abs(x)<=1&&Mathf.Abs(y)<=1;}
                    // the stand is hidden when the camera stands in it
                    bool standShown=plan.SideVisible(bp.Block.Side,cam);vis&=standShown;
                    all++;if(vis)seen++;bool own=bp.Block.Side==2?bx<=-10:bx>=10;if(own){half++;if(vis)halfSeen++;}}
                line+=$"  side{bp.Block.Side} role{bp.Block.Role}: all={100f*seen/all:0}% ownHalf(|x|>=10)={100f*halfSeen/half:0}%";}
            Console.WriteLine(line);
        }
    }
}

