using System;
using UnityEngine;
public static class Parity {
    // Piece-by-piece equality of the Release 130 generator (git acb5408f) and the new legacy path.
    public static void Run(){
        int plans=0,pieces=0,mismatches=0;string first=null;
        var ids=new System.Collections.Generic.List<string>(Doppel6.Old.ClubStadiumProfiles.KnownClubIds);ids.Add(null);ids.Add("");ids.Add("XYZ-9");ids.Add("NED-1");ids.Add("GER-C7");
        foreach(var id in ids)foreach(var detailed in new[]{true,false})foreach(var (L,W) in new[]{(68f,44f),(105f,68f),(81.6f,52.8f)})foreach(var (home,trim) in new[]{(new Color(.8f,.1f,.15f),Color.white),(new Color(.11f,.19f,.27f),new Color(.95f,.9f,.2f))}){
            var oldPlan=Doppel6.Old.StadiumArchitecture.Plan(Doppel6.Old.ClubStadiumProfiles.Resolve(id),L,W,home,trim,detailed);
            var newProfile=Doppel6.Probe.ClubStadiumProfiles.ResolveLegacy(id);var newPlan=Doppel6.Probe.StadiumArchitecture.Plan(newProfile,L,W,home,trim,detailed,false);
            plans++;
            bool Same(){
                if(oldPlan.Pieces.Count!=newPlan.Pieces.Count){Note($"{id} {detailed} {L}: piece count {oldPlan.Pieces.Count} vs {newPlan.Pieces.Count}");return false;}
                for(int i=0;i<oldPlan.Pieces.Count;i++){var a=oldPlan.Pieces[i];var b=newPlan.Pieces[i];pieces++;
                    bool eq=a.slot.ToString()==b.slot.ToString()&&a.shape.ToString()==b.shape.ToString()&&a.group==b.group&&a.center.x==b.center.x&&a.center.y==b.center.y&&a.center.z==b.center.z&&a.size.x==b.size.x&&a.size.y==b.size.y&&a.size.z==b.size.z
                        &&a.rotation.x==b.rotation.x&&a.rotation.y==b.rotation.y&&a.rotation.z==b.rotation.z&&a.rotation.w==b.rotation.w&&a.tint==b.tint&&a.crowdU==b.crowdU&&a.crowdRow==b.crowdRow&&b.sides==0;
                    if(!eq){Note($"{id} {detailed} {L}: piece {i} {a.group}/{a.slot}/{a.shape} c={a.center} s={a.size} vs {b.group}/{b.slot}/{b.shape} c={b.center} s={b.size} rot {a.rotation.x},{a.rotation.y},{a.rotation.z},{a.rotation.w} vs {b.rotation.x},{b.rotation.y},{b.rotation.z},{b.rotation.w}");return false;}}
                for(int s=0;s<4;s++)if(oldPlan.Fronts[s]!=newPlan.Fronts[s]||oldPlan.CameraFronts[s]!=newPlan.CameraFronts[s]){Note($"{id}: fronts differ at {s}");return false;}
                if(oldPlan.Identity!=newPlan.Identity||oldPlan.Accent!=newPlan.Accent||oldPlan.SeatColor!=newPlan.SeatColor||oldPlan.CrowdDensity!=newPlan.CrowdDensity||oldPlan.TurfA!=newPlan.TurfA||oldPlan.TurfB!=newPlan.TurfB||oldPlan.Wear!=newPlan.Wear||oldPlan.PitchStripes!=newPlan.PitchStripes||oldPlan.PitchPattern!=newPlan.PitchPattern||oldPlan.Archetype!=newPlan.Archetype||oldPlan.Motif!=newPlan.Motif){Note($"{id}: plan fields differ");return false;}
                foreach(var kv in oldPlan.Colors){var slot=(Doppel6.Probe.StadiumSlot)Enum.Parse(typeof(Doppel6.Probe.StadiumSlot),kv.Key.ToString());if(newPlan.Colors[slot]!=kv.Value){Note($"{id}: colour {kv.Key} differs");return false;}}
                if(newPlan.Blocks.Count!=0){Note($"{id}: legacy plan reserved supporter blocks");return false;}
                var op=Doppel6.Old.ClubStadiumProfiles.Resolve(id);if(op.ClubId!=newProfile.ClubId||op.DisplayName!=newProfile.DisplayName||op.DetailSeed!=newProfile.DetailSeed){Note($"{id}: profile identity differs");return false;}
                return true;
            }
            if(!Same())mismatches++;
        }
        void Note(string s){if(first==null)first=s;}
        Console.WriteLine($"legacy parity: plans={plans} pieces={pieces} mismatching plans={mismatches}"+(first!=null?" first: "+first:""));
    }
}

