using UnityEngine;
using Doppel6.Probe;
public static class Dump {
    static string Hash(IEnumerable<float> values){unchecked{ulong h=1469598103934665603UL;foreach(var f in values){var b=BitConverter.GetBytes(f);foreach(var x in b){h^=x;h*=1099511628211UL;}}return h.ToString("x16");}}
    static IEnumerable<float> V3(IEnumerable<Vector3> v){foreach(var p in v){yield return p.x;yield return p.y;yield return p.z;}}
    static IEnumerable<float> C(IEnumerable<Color> v){foreach(var p in v){yield return p.r;yield return p.g;yield return p.b;yield return p.a;}}
    static string Tex(Texture2D t)=>t==null?"null":$"tex {t.width}x{t.height} wrap={t.wrapMode} filter={t.filterMode} aniso={t.anisoLevel} px={Hash(C(t.pixels))}";
    static string Mat(Material m){if(m==null)return "null";var parts=new List<string>{"shader="+m.shader?.name};var list=new List<KeyValuePair<string,object>>(m.Values);list.Sort((a,b)=>string.CompareOrdinal(a.Key,b.Key));
        foreach(var kv in list){string v=kv.Value is Color c?Hash(C(new[]{c})):kv.Value is Texture2D t?Tex(t):kv.Value is Vector2 v2?$"{v2.x:R},{v2.y:R}":kv.Value is Vector4 v4?$"{v4.x:R},{v4.y:R},{v4.z:R},{v4.w:R}":kv.Value is float f?f.ToString("R"):kv.Value?.ToString();parts.Add(kv.Key+"="+v);}
        return string.Join(" ",parts);}
    public static string World(Transform world){
        var s=new StringBuilder();void Walk(Transform t,string path){foreach(var child in t.children){var p=path+"/"+child.gameObject.name;var r=child.GetComponent<MeshRenderer>();var f=child.GetComponent<MeshFilter>();
            s.Append(p).Append(" pos=").Append(Hash(V3(new[]{child.position,child.localScale}))).Append(" active=").Append(child.gameObject.activeSelf);
            if(f!=null&&f.sharedMesh!=null){var m=f.sharedMesh;s.Append(" mesh=").Append(m.name).Append(" v=").Append(Hash(V3(m.vertices))).Append(" n=").Append(Hash(V3(m.normals))).Append(" c=").Append(Hash(C(m.colors))).Append(" t=").Append(m.triangles.Length);}
            if(r!=null)s.Append(" shadow=").Append(r.shadowCastingMode).Append(" receive=").Append(r.receiveShadows).Append(" mat{").Append(Mat(r.sharedMaterial)).Append("}");
            s.Append('\n');Walk(child,p);}}
        Walk(world,"");return s.ToString();
    }
}
public static class BridgeDump {
